#include <sstream>
#include <string>
#include <vector>
#include <unistd.h>

struct Urn { std::string path, id, day; int n = 0; };

static bool parse_urn(const std::string &path, Urn &u) {
    std::ifstream in(path);
    std::string banner, a, b, c, extra;
    if (!std::getline(in, banner) || banner != "URN1" ||
        !std::getline(in, a) || !std::getline(in, b) || !std::getline(in, c) ||
        std::getline(in, extra)) return false;
    if (a.rfind("id ", 0) != 0 || b.rfind("day ", 0) != 0 || c.rfind("n ", 0) != 0) return false;
    u.path = path; u.id = a.substr(3); u.day = b.substr(4);
    if (u.id.empty() || u.id.find_first_of(" \t/\\") != std::string::npos ||
        !std::regex_match(u.day, std::regex("[0-9]{4}-[0-9]{2}-[0-9]{2}"))) return false;
    char *end = nullptr; errno = 0;
    long value = std::strtol(c.c_str() + 2, &end, 10);
    if (errno || !end || *end != '\0' || value < INT_MIN || value > INT_MAX) return false;
    u.n = static_cast<int>(value);
    return true;
}

static void read_existing(std::map<std::string, long long> &days) {
    std::ifstream in("/app/inkpit/counts.json");
    std::ostringstream ss; ss << in.rdbuf();
    const std::string text = ss.str();
    const std::regex pair("\\\"([0-9]{4}-[0-9]{2}-[0-9]{2})\\\"[[:space:]]*:[[:space:]]*(-?[0-9]+)");
    for (std::sregex_iterator it(text.begin(), text.end(), pair), end; it != end; ++it)
        days[(*it)[1].str()] += std::stoll((*it)[2].str());
}

static bool replace_file(const std::string &tmp, const std::string &dst, const std::string &body) {
    { std::ofstream out(tmp, std::ios::trunc); if (!out) return false; out << body; if (!out) return false; }
    return rename(tmp.c_str(), dst.c_str()) == 0;
}

int n_fold(void) {
    std::vector<std::string> paths;
    DIR *dir = opendir("/app/snapvat/live");
    if (!dir) return 1;
    while (dirent *ent = readdir(dir)) {
        std::string name = ent->d_name;
        if (name.size() >= 4 && name.substr(name.size() - 4) == ".urn")
            paths.push_back("/app/snapvat/live/" + name);
    }
    closedir(dir);
    std::sort(paths.begin(), paths.end());
    if (paths.empty()) return 2;

    std::vector<Urn> urns;
    for (const auto &path : paths) {
        Urn u;
        if (!parse_urn(path, u)) return 1;
        urns.push_back(u);
    }
    std::map<std::string, long long> days;
    read_existing(days);
    for (const auto &u : urns) days[u.day] += u.n;
    const std::string cover = urns.back().id;

    std::ostringstream daytext, emit;
    for (const auto &kv : days) {
        daytext << kv.first << ' ' << kv.second << '\n';
        emit << kv.first << ' ' << kv.second << '\n';
    }
    emit << "covers " << cover << '\n';
    if (!replace_file("/app/snapvat/days.new", "/app/snapvat/days.tmp", daytext.str())) return 1;
    if (!replace_file("/app/inkpit/emit.new", "/app/inkpit/emit.inc", emit.str())) return 1;
    { std::ofstream out("/app/snapvat/last.id", std::ios::trunc); if (!out) return 1; out << cover << '\n'; }
    { std::ofstream out("/app/snapvat/folded.list", std::ios::trunc); if (!out) return 1; for (const auto &u : urns) out << u.path << '\n'; }
    return 0;
